select lbd.id, lbd.track_no, lbd.platform_order_no, lb.carrier_id as carrierId, lb.tel_number as telNumber, lb.channel_id as channelId, lb.transport_no as transportNo, lc.track_query_type as trackQueryType from logistics_bill_detail lbd inner join logistics_bill lb on lbd.main_id = lb.id and lb.is_deleted = false LEFT JOIN logistics_channel lc on lb.channel_id = lc.id and lc.is_deleted = false where lbd.track_status not in('sign','manualComplete','systemComplete','deliveryFail') and (lbd.track_no != '' or lb.transport_no != '') and lbd.is_deleted = false
and lbd.track_time > #{query.trackTime}
and lb.order_type in ('B2B','B2C','AfterSale')
and lb.order_type = 'firstMile'
and (lc.track_query_mode = #{query.trackQueryMode} or lc.track_query_mode is NULL)
and lbd.register_status = #{query.registerStatus}
and lbd.track_enable = #{query.trackEnable}
and lbd.track_no in
#{item}
and lb.transport_no in
#{item}
ORDER BY lbd.update_time,lbd.version LIMIT #{query.size}

SELECT lbd.id, lbd.track_no, lbd.platform_order_no, lbd.register_status, lb.carrier_id AS carrierId, lb.tel_number AS telNumber, lb.channel_id AS channelId, lb.channel_name AS channelName, lb.transport_no AS transportNo, lb.sales_platform AS salesPlatform, lb.shop_id AS shopId, lc.track_query_type AS trackQueryType, best_match.cfgId as thirdRefId, best_match.cfgTime, best_match.thirdChannelName, best_match.isPushMobile, best_match.pushType, best_match.platformType, lb.delivery_time FROM logistics_bill_detail lbd INNER JOIN logistics_bill lb ON lbd.main_id = lb.id AND lb.is_deleted = false LEFT JOIN logistics_channel lc ON lb.channel_id = lc.id AND lc.is_deleted = false INNER JOIN LATERAL ( SELECT matched.cfgId, matched.cfgTime, matched.platformType, matched.thirdChannelName, matched.isPushMobile, matched.pushType FROM ( SELECT , 1 as priority FROM logistics_third_channel_ref ltcr WHERE AND ltcr.logistics_supplier_id = lb.logistics_supplier_id AND ltcr.logistics_channel_id = lb.channel_id UNION ALL SELECT , 2 as priority FROM logistics_third_channel_ref ltcr WHERE AND ltcr.logistics_supplier_id = lb.logistics_supplier_id AND ltcr.logistics_channel_id = 'all' UNION ALL SELECT , 3 as priority FROM logistics_third_channel_ref ltcr WHERE AND ltcr.logistics_supplier_id = 'all' AND ltcr.logistics_channel_id = 'all' ) matched ORDER BY matched.priority LIMIT 1 ) AS best_match ON TRUE WHERE lbd.is_deleted = false
and lbd.track_time > #{query.trackTime}
and lbd.track_time < #{query.trackEndTime}
and lbd.register_status = #{query.registerStatus}
and lbd.track_enable = #{query.trackEnable}
AND lbd.track_status NOT IN ('sign','manualComplete','systemComplete','deliveryFail') AND (lbd.track_no != '' OR lb.transport_no != '')
AND lb.order_type IN ('B2B','B2C','AfterSale')
AND lb.order_type = 'firstMile'
AND lbd.track_no IN
#{item}
AND lb.transport_no IN
#{item}
and lb.sales_platform = #{query.salesPlatform}
AND lb.delivery_time >= best_match.cfgTime ORDER BY lbd.update_time,lbd.version LIMIT #{query.size}
